import * as O from './orig.mjs';
import * as N from './new.mjs';
const names = ['jung','kim','lee','park','choi'];
const eq = (a, b) => Object.is(a, b) || JSON.stringify(a) === JSON.stringify(b) && Object.keys(a ?? {}).join() === Object.keys(b ?? {}).join();
let fails = 0, n = 0;
const check = (label, a, b) => { n++; if (!eq(a, b)) { fails++; if (fails < 10) console.log('MISMATCH', label, a, b); } };
// publicFields
for (let i = 0; i < 20000; i++) {
  const row = { id: Math.floor(Math.random()*10), name: names[i%5], age: 18+Math.floor(Math.random()*43) };
  check('pf', O.publicFields(row), N.publicFields(row));
}
// totalAge
for (let i = 0; i < 20000; i++) {
  const len = Math.floor(Math.random()*13);
  const rows = Array.from({length: len}, () => ({ id: Math.floor(Math.random()*10), name: names[Math.floor(Math.random()*5)], age: 18+Math.floor(Math.random()*43) }));
  check('ta', O.totalAge(rows), N.totalAge(rows));
}
// parseAmount: random strings over the alphabet, length 0..8
const alpha = '0123456789.+- ex';
for (let i = 0; i < 2000000; i++) {
  const len = Math.floor(Math.random()*9);
  let s = ''; for (let j = 0; j < len; j++) s += alpha[Math.floor(Math.random()*alpha.length)];
  check('pa:' + JSON.stringify(s), O.parseAmount(s), N.parseAmount(s));
}
// exhaustive over short strings (length 0..3) of the alphabet
const all = [''];
let frontier = [''];
for (let L = 1; L <= 4; L++) { const next = []; for (const p of frontier) for (const c of alpha) next.push(p + c); all.push(...next); frontier = next; }
for (const s of all) check('ex:' + JSON.stringify(s), O.parseAmount(s), N.parseAmount(s));
// the given examples
check('ex1', O.publicFields({id:1,name:'jung',age:24}), N.publicFields({id:1,name:'jung',age:24}));
check('ex2', O.totalAge([{id:9,name:'kim',age:45},{id:6,name:'park',age:30},{id:9,name:'lee',age:49}]), N.totalAge([{id:9,name:'kim',age:45},{id:6,name:'park',age:30},{id:9,name:'lee',age:49}]));
check('ex3', O.parseAmount('92858+99'), N.parseAmount('92858+99'));
check('ex4', O.parseAmount('.72e'), N.parseAmount('.72e'));
check('empty totalAge', O.totalAge([]), N.totalAge([]));
console.log(`checked ${n}, mismatches ${fails}`);
console.log('sample parse:', ['92858+99','.72e','', ' 12 ','1e3','0x1f','-0x1f'].map(s => [s, O.parseAmount(s), N.parseAmount(s)]));
EOF
cd "$S" && node check.mjs

